<?php require 'includes/db.php';require 'includes/helpers.php';require_login();ensure_default_categories($pdo);$cats=categories($pdo);$edit=null;$error='';$id=(int)($_GET['id']??0);if($id){$q=$pdo->prepare("SELECT * FROM transactions WHERE id=? AND user_id=?");$q->execute([$id,user_id()]);$edit=$q->fetch(PDO::FETCH_ASSOC);}
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$amount=(float)($_POST['amount']??0);$type=$_POST['type']??'expense';$cat=(int)$_POST['category_id'];$method=$_POST['payment_method']??'Cash';$date=$_POST['date']??date('Y-m-d');$notes=trim($_POST['notes']??'');if(!$title||$amount<=0||!$cat)$error='Please fill all required fields.';else{if($id){$q=$pdo->prepare("UPDATE transactions SET title=?,amount=?,type=?,category_id=?,payment_method=?,date=?,notes=? WHERE id=? AND user_id=?");$q->execute([$title,$amount,$type,$cat,$method,$date,$notes,$id,user_id()]);}else{$q=$pdo->prepare("INSERT INTO transactions(user_id,title,amount,type,category_id,payment_method,date,notes) VALUES(?,?,?,?,?,?,?,?)");$q->execute([user_id(),$title,$amount,$type,$cat,$method,$date,$notes]);}header('Location:transactions.php');exit;}}
$v=$edit?:['title'=>'','amount'=>'','type'=>'expense','category_id'=>'','payment_method'=>'Cash','date'=>date('Y-m-d'),'notes'=>''];?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $edit?'Edit':'Add'?> Transaction</title><link rel="stylesheet" href="assets/style.css"></head><body class="<?=!empty($_SESSION['dark'])?'dark':''?>"><div class="app"><aside class="sidebar"><?php include 'includes/nav.php';?></aside><main class="main"><header class="top"><div><h1><?= $edit?'Edit':'Add'?> Transaction</h1><p>Record your income or spending</p></div></header><div class="form-card"><?php if($error):?><div class="alert"><?=h($error)?></div><?php endif;?><form method="post"><input type="hidden" name="id" value="<?=$id?>"><div class="formgrid"><label>Title *<input name="title" value="<?=h($v['title'])?>" placeholder="e.g. Grocery shopping" required></label><label>Amount *<input type="number" step="0.01" min="0.01" name="amount" value="<?=h($v['amount'])?>" required></label><label>Type<select name="type"><option value="expense" <?=$v['type']==='expense'?'selected':''?>>Expense</option><option value="income" <?=$v['type']==='income'?'selected':''?>>Income</option></select></label><label>Category<select name="category_id" required><option value="">Choose category</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$v['category_id']==$c['id']?'selected':''?>><?=h($c['icon'].' '.$c['name'])?></option><?php endforeach;?></select></label><label>Payment Method<select name="payment_method"><?php foreach(['Cash','UPI','Debit Card','Credit Card','Bank Transfer','Other'] as $m):?><option <?=$v['payment_method']===$m?'selected':''?>><?=$m?></option><?php endforeach;?></select></label><label>Date<input type="date" name="date" value="<?=h($v['date'])?>"></label><label class="full">Notes<textarea name="notes" rows="4" placeholder="Optional notes"><?=h($v['notes'])?></textarea></label></div><div class="actions"><a class="btn" href="transactions.php">Cancel</a><button class="btn primary"><?= $edit?'Update':'Save'?> Transaction</button></div></form></div></main></div></body></html>